import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation to provide a space-efficient probabilistic data structure to test 
    whether an element is a member of a set without false negatives and with a specified false positive rate.

    The optimal bit array size and number of hash functions are calculated based on the expected 
    number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal size of bit array (m) and number of hash functions (k)
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_number_of_hashes(expected_items, self.size)

        # Initialize bit array with all bits set to 0
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """ Calculate the optimal size of the bit array needed. """
        return math.ceil((n * math.log(p)) / math.log(1 / (2 ** math.log(2))))

    def _optimal_number_of_hashes(self, n: int, m: int) -> int:
        """ Calculate the optimal number of hash functions needed. """
        return max(1, int(math.ceil((m / n) * math.log(2))))

    def _hash(self, item: str, seed: int) -> int:
        """ Create a hash for the given item using a specified seed. """
        hash_result = hashlib.md5((item + str(seed)).encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """ Add an item to the Bloom Filter. """
        for i in range(self.hash_count):
            hash_index = self._hash(item, i)
            self.bit_array[hash_index] = 1

    def contains(self, item: str) -> bool:
        """ Check if an item is possibly in the Bloom Filter. """
        for i in range(self.hash_count):
            hash_index = self._hash(item, i)
            if self.bit_array[hash_index] == 0:
                return False
        return True

